/**
 * Gitleaks Report Parser
 * Expects JSON array format generated by `gitleaks detect --report-format json`
 */
export const gitleaksParser = {
  name: 'gitleaks',
  scanType: 'Secret',

  parse: (report) => {
    // Gitleaks output can be an array of findings or an empty string/null if clean
    if (!report) return [];

    let leaks = [];
    if (Array.isArray(report)) {
      leaks = report;
    } else if (typeof report === 'object' && Array.isArray(report.leaks)) {
      leaks = report.leaks;
    } else {
      const error = new Error('Invalid Gitleaks report format: Expected JSON array of leaks');
      error.statusCode = 422;
      throw error;
    }

    const redactSecret = (raw) => {
      if (!raw || typeof raw !== 'string') return '[REDACTED]';
      if (raw.length <= 4) return '****';
      const visible = raw.slice(0, 4);
      return `${visible}${'*'.repeat(Math.min(raw.length - 4, 20))}`;
    };

    return leaks.map((leak) => {
      const ruleId = leak.RuleID || 'generic-api-key';
      const file = leak.File || leak.file || 'unknown-file';
      const line = leak.StartLine || leak.startLine || 1;
      const commit = leak.Commit || leak.commit || 'uncommitted';
      const redactedPreview = redactSecret(leak.Secret || leak.secret || '');

      return {
        title: `Exposed Credential: ${leak.Description || ruleId}`,
        description: `Potential sensitive credential or secret leaked in code repository at ${file}:${line}. Redacted pattern: ${redactedPreview}. Identified in commit: ${commit}.`,
        severity: 'Critical',
        cve: ruleId.toUpperCase(),
        cwe: ['CWE-798', 'CWE-200'], // Use of Hard-coded Credentials / Exposure of Sensitive Info
        cvss: 8.9,
        tool: 'gitleaks',
        scanType: 'Secret',
        component: ruleId,
        version: 'git-head',
        fixedVersion: 'Immediate Revocation & Rotation',
        filePath: file,
        line: parseInt(line, 10) || 1,
        remediationGuidance:
          '1. Immediately revoke and rotate the exposed secret token in the third-party provider.\n2. Invalidate prior active sessions.\n3. Remove the secret from Git history using git-filter-repo or BFG Repo-Cleaner.'
      };
    });
  }
};

export default gitleaksParser;
